(25356, 'Luke 22:16', 'Luke', 22, 16, 'ځکه زه تاسو ته وایم چې ترڅو پورې د فسحې د قربانۍ مقصد د خدای په پاچاهۍ کې پوره نه شي، تر هغې پورې به نور دا ډوډۍ ونه خورم.»', 'جکه زه تاسو ته وایم چې ترچو پورې د فسحې د قربانی مقصد د خدای په پاچاهی کې پوره نه شی، تر هغې پورې به نور دا دودی ونه خورم.»', 'NT', 'afghan2023', 'afghan', '', '', 1761237833, 1761237833),
(25357, 'Luke 22:17', 'Luke', 22, 17, 'بیا عیسی پیاله راواخیستله، شکر یې وویست او ویې ویل: «دا واخلئ او په خپل منځ کې یې ووېشئ.', 'بیا عیسی پیاله راواخیستله، شکر یې وویست او ویې ویل: «دا واخلی او په خپل منج کې یې ووېشی.', 'NT', 'afghan2023', 'afghan', '', '', 1761237833, 1761237833),
(25358, 'Luke 22:18', 'Luke', 22, 18, 'ځکه زه تاسو ته وایم چې له دې وروسته به تر هغې پورې د انګورو شربت ونه څښم، ترڅو د خدای پاچاهي رانه شي.»', 'جکه زه تاسو ته وایم چې له دې وروسته به تر هغې پورې د انګورو شربت ونه چشم، ترچو د خدای پاچاهی رانه شی.»', 'NT', 'afghan2023', 'afghan', '', '', 1761237833, 1761237833),
(25359, 'Luke 22:19', 'Luke', 22, 19, 'بیا هغه یوه ډوډۍ راواخیستله، شکر یې پرې وویست، هغه یې ماته کړه او هغوی ته یې ورکړه او ویې ویل: «دا زما بدن دی چې ستاسو دپاره ورکول کیږي. زما په یاد همداسې کوئ.»', 'بیا هغه یوه دودی راواخیستله، شکر یې پرې وویست، هغه یې ماته کره او هغوی ته یې ورکره او ویې ویل: «دا زما بدن دی چې ستاسو دپاره ورکول کیزی. زما په یاد همداسې کوی.»', 'NT', 'afghan2023', 'afghan', '', '', 1761237833, 1761237833),
(25360, 'Luke 22:20', 'Luke', 22, 20, 'په همدې ډول د ماښام ډوډۍ څخه وروسته یې پیاله راواخیستله او ویې ویل: «دا پیاله د خدای او انسانانو ترمنځ نوی لوظ دی چې زما د وینې په وسیله جوړیږي چې ستاسو دپاره توییږي.', 'په همدې دول د ماشام دودی چخه وروسته یې پیاله راواخیستله او ویې ویل: «دا پیاله د خدای او انسانانو ترمنج نوی لوظ دی چې زما د وینې په وسیله جوریزی چې ستاسو دپاره توییزی.', 'NT', 'afghan2023', 'afghan', '', '', 1761237833, 1761237833);